147:pub(crate) fn windows_input_bindings_digest(inputs: &[EffectiveInputBinding]) -> String {
148:    let mut ordered = inputs.iter().collect::<Vec<_>>();
149:    ordered.sort_by(|left, right| {
150:        left.presentation_relative_path
151:            .cmp(&right.presentation_relative_path)
152:    });
153:    let mut directories = BTreeSet::<String>::new();
154:    for input in &ordered {
155:        let components = input
156:            .presentation_relative_path
157:            .split('/')
158:            .collect::<Vec<_>>();
159:        for end in 1..components.len() {
160:            directories.insert(components[..end].join("/"));
161:        }
162:    }
163:    let mut bytes = b"windows-immutable-input-tree-v2\0".to_vec();
164:    for directory in directories {
165:        bytes.extend_from_slice(b"D\0");
166:        bytes.extend_from_slice(directory.as_bytes());
167:        bytes.push(0);
168:    }
169:    for input in ordered {
170:        bytes.extend_from_slice(b"F\0");
171:        bytes.extend_from_slice(input.presentation_relative_path.as_bytes());
172:        bytes.push(0);
173:        bytes.extend_from_slice(input.digest.as_bytes());
174:        bytes.push(0);
175:        bytes.extend_from_slice(input.byte_length.to_string().as_bytes());
176:        bytes.push(0);
177:    }
178:    sha256_bytes(&bytes)
179:}
