181:fn adaptive_poll_delay(poll_index: usize) -> Duration {
182:    Duration::from_millis(
183:        ADAPTIVE_POLL_DELAYS_MS[poll_index.min(ADAPTIVE_POLL_DELAYS_MS.len() - 1)],
184:    )
185:}
