187:fn sleep_until_poll(deadline: Instant, poll_index: &mut usize) {
188:    let remaining = deadline.saturating_duration_since(Instant::now());
189:    if remaining.is_zero() {
190:        return;
191:    }
192:    thread::sleep(adaptive_poll_delay(*poll_index).min(remaining));
193:    *poll_index = poll_index.saturating_add(1);
194:}
